// Types for mermaid-ascii.js, generated by scripts/vendor/build.mjs from beautiful-mermaid.

export interface AsciiTheme {
  fg: string
  border: string
  line: string
  arrow: string
  corner?: string
  junction?: string
  accent?: string
  bg?: string
}

export interface AsciiRenderOptions {
  useAscii?: boolean
  paddingX?: number
  paddingY?: number
  boxBorderPadding?: number
  colorMode?: 'none' | 'html'
  theme?: Partial<AsciiTheme>
}

export function renderMermaidAscii(text: string, options?: AsciiRenderOptions): string

// Plot area of the next xychart rendered, in cells.
export function setChartSize(width: number, height: number): void

// The colours an xychart gives its series under `theme`, in series order.
export function seriesColors(total: number, theme: AsciiTheme): string[]
